import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// The game's sound effects. The files are generated by tool/generate_sounds.py.
enum Sfx {
  tap('tap.wav'),
  step('step.wav'),
  bump('bump.wav'),
  tryAgain('try_again.wav'),
  success('success.wav'),
  star('star.wav');

  const Sfx(this.file);
  final String file;
}

/// Plays sound effects. Screens use this interface, so tests can swap in [RecordingSoundService].
abstract class SoundService {
  /// Whether sound is muted. Widgets listen to this to update the mute button.
  ValueListenable<bool> get muted;

  Future<void> setMuted(bool value);

  /// Plays [sfx] unless muted. Never throws: a missing sound must not break the game.
  Future<void> play(Sfx sfx);
}

class AudioSoundService implements SoundService {
  AudioSoundService({FlutterSecureStorage? storage}) : _storage = storage ?? const FlutterSecureStorage() {
    _restoreMuted();
  }

  final FlutterSecureStorage _storage;
  final _muted = ValueNotifier<bool>(false);
  // One player per effect, so a fast run of steps restarts its own sound instead of cutting off others.
  final Map<Sfx, AudioPlayer> _players = {};
  static const _mutedKey = 'sound_muted';

  @override
  ValueListenable<bool> get muted => _muted;

  Future<void> _restoreMuted() async {
    try {
      _muted.value = await _storage.read(key: _mutedKey) == 'true';
    } catch (_) {
      // Storage unavailable: keep sound on.
    }
  }

  @override
  Future<void> setMuted(bool value) async {
    _muted.value = value;
    if (value) {
      for (final p in _players.values) {
        await p.stop();
      }
    }
    try {
      await _storage.write(key: _mutedKey, value: '$value');
    } catch (_) {}
  }

  @override
  Future<void> play(Sfx sfx) async {
    if (_muted.value) return;
    try {
      final player = _players.putIfAbsent(sfx, () => AudioPlayer()..setReleaseMode(ReleaseMode.stop));
      await player.stop();
      await player.play(AssetSource('sounds/${sfx.file}'));
    } catch (e) {
      debugPrint('Could not play ${sfx.name}: $e');
    }
  }
}

/// Records what would have played. Used in tests, and anywhere audio isn't available.
class RecordingSoundService implements SoundService {
  final played = <Sfx>[];
  final _muted = ValueNotifier<bool>(false);

  @override
  ValueListenable<bool> get muted => _muted;

  @override
  Future<void> setMuted(bool value) async => _muted.value = value;

  @override
  Future<void> play(Sfx sfx) async {
    if (!_muted.value) played.add(sfx);
  }
}
